def semver_sort(versions):
    def parse_version(version):
        # Split version into core and optional pre-release/build
        core = version
        pre_release = ""
        build = ""

        # Find build metadata (everything after +)
        if '+' in version:
            core, build = version.rsplit('+', 1)

        # Find pre-release (everything after first -)
        if '-' in core:
            core, pre_release = core.split('-', 1)

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        pre_release_parts = []
        if pre_release:
            pre_release_parts = pre_release.split('.')

        return (major, minor, patch, pre_release_parts)

    def compare_key(version_string):
        major, minor, patch, pre_release_parts = parse_version(version_string)

        # Convert pre-release parts to a sortable format
        # If there's no pre-release, it sorts after the version with pre-release
        # So we use a tuple where presence of pre-release affects sorting
        if not pre_release_parts:
            # No pre-release: sorts after pre-release versions
            pre_release_key = (1,)  # 1 means no pre-release (sorts later)
        else:
            # Convert each identifier for comparison
            converted = []
            for identifier in pre_release_parts:
                if identifier.isdigit():
                    # All-digit: sort numerically, and before non-digit
                    converted.append((0, int(identifier)))
                else:
                    # Non-digit: sort by ASCII, and after all-digit
                    converted.append((1, identifier))
            pre_release_key = (0, tuple(converted))  # 0 means has pre-release (sorts earlier)

        return (major, minor, patch, pre_release_key)

    # Sort using the key function, maintaining stable sort for equal precedence
    return sorted(versions, key=compare_key)

